import {CHARACTERS,QUESTS} from '../data/campaign.js';
import {STAGES,stats} from '../data/stages.js';
const $=id=>document.getElementById(id);
export class MainLobby {
 constructor(rpg){this.rpg=rpg;this.entering=false;}
 splash(){const g=this.rpg.game;g.view('splash',`<button id="touch-start" class="splash-scene" aria-label="화면을 터치하면 시작합니다."><div class="splash-logo"><small>BUCHEON MUSEUM · THE TWILIGHT ARCHIVE</small><span>박물관의 황혼</span><h1>여월의 밤</h1><p>잊힌 기억이, 다시 빛나는 시간</p></div><span class="touch-start-copy">화면을 터치하면 시작합니다.</span><span class="splash-foot">기억을 잇고 시간을 복원하는 모험</span></button>`);$('touch-start').onclick=()=>this.enter();}
 async enter(){if(this.entering)return;this.entering=true;const g=this.rpg.game;g.view('entrance',`<section class="entrance-loading"><span>☾</span><h1>여월의 문을 여는 중</h1><p>박물관의 기억을 불러옵니다.</p></section>`);try{await g.display.enter();if(g.state==='entrance')this.rpg.home();}finally{this.entering=false;}}
 render(){const r=this.rpg,g=r.game,c=r.active?r.character:CHARACTERS[0],s=stats(g.save),fragments=r.active?g.save.fragments.reduce((a,b)=>a+b,0):0,restored=r.active?Math.round(g.save.restored.reduce((a,b)=>a+b,0)/6):0,done=r.active?g.save.cleared.length:0,pending=r.active?QUESTS.filter(q=>r.quests.eligible(q)&&!r.data.quests[q.id]?.done):[];
 const icon=(id,symbol,label)=>`<button id="main-${id}" class="lobby-medallion"><span>${symbol}</span><b>${label}</b></button>`;
 g.view('main-lobby',`<section class="museum-main" aria-label="여월의 밤 메인 로비"><header class="main-status"><div class="curator-badge"><span>☾</span><div><small>${r.active?`학예사 · ${r.data.cycle}회차`:'박물관의 황혼'}</small><b>${r.active?c.name:'여월의 밤'}</b></div></div><div class="resource-pill"><span>◈</span><small>복원 파편</small><b>${fragments}</b></div><div class="resource-pill"><span>✦</span><small>정화 구역</small><b>${done} / 6</b></div><div class="resource-pill"><span>◇</span><small>박물관 복원</small><b>${restored}%</b></div><button id="main-settings" aria-label="환경설정">⚙</button></header><aside class="main-collection"><small>CURATOR'S COLLECTION</small><h2>기억의 서재</h2><div>${icon('character','♙','학예사 선택')}${icon('catalog','▤','유물 도록')}${icon('journal','✧','연구 일지')}${icon('bestiary','♜','수호자 도감')}</div><button id="main-prologue" class="main-story">☾ 여월의 이야기 <span>프롤로그 보기 →</span></button></aside><div class="main-hero" aria-label="${c.name} 캐릭터"><div class="main-hero-aura"></div><img class="main-hero-portrait" src="./assets/${c.lobbyArt || c.id + '-lobby-portrait.png'}" alt="${c.name} · 유물의 기억을 다루는 학예사 일러스트" draggable="false"><div class="main-hero-name"><small>${c.role}</small><h2>${c.name}</h2><p>${r.active?`생명 ${s.hp+c.hp} · 정화력 ${s.attack+c.attack}`:'달빛을 따라 기억 속으로'}</p></div></div><aside class="main-missions"><small>오늘의 박물관</small><h2>기억을 잇는 여정</h2><button id="main-desk" class="desk-card"><span>⌂</span><strong>안내 데스크</strong><small>점동이 · 의뢰 수령과 보고</small><b>방문하기 →</b></button><button id="main-quests" class="mission-card"><small>받은 의뢰 ${pending.length}</small><strong>${pending[0]?.name||'안내 데스크에서 시작하세요'}</strong><span>의뢰 일지 →</span></button></aside><nav class="main-bottom" aria-label="메인 로비 메뉴"><div class="main-facilities">${icon('equipment','▣','가방 · 장착')}${icon('skills','✦','유물 스킬')}${icon('restore','♨','유물 복원대')}${icon('map','⌘','탐험 지도')}</div><div class="main-journey"><button id="main-return-title">시작 화면</button><button id="main-adventure"><span>⚔</span><b>모험</b><small>밤의 전시실 →</small></button></div></nav><span class="main-location">여월동 · 달빛 정원</span></section>`);
 const guard=fn=>r.active?fn():r.hub.registrationNotice();
 $('main-settings').onclick=()=>g.settings();$('main-desk').onclick=()=>r.desk();$('main-character').onclick=()=>g.boot();$('main-catalog').onclick=()=>r.hub.catalog();$('main-journal').onclick=()=>guard(()=>g.journal());$('main-bestiary').onclick=()=>g.bestiary();$('main-prologue').onclick=()=>g.story();$('main-quests').onclick=()=>guard(()=>r.journal());$('main-equipment').onclick=()=>guard(()=>r.equipment());$('main-restore').onclick=()=>guard(()=>g.restoration());$('main-map').onclick=()=>guard(()=>r.showMap());$('main-adventure').onclick=()=>r.active?g.exhibitions():g.boot();$('main-return-title').onclick=()=>this.splash();$('main-skills').onclick=()=>g.dialog(`<small>RELIC ABILITIES</small><h2>유물에 깃든 힘</h2><div class="relic-list">${STAGES.map((st,i)=>`<article><h3>${st.icon} ${st.skill}</h3><p>${r.active&&g.save.cleared.includes(i)?'획득 완료 · 전투에서 사용 가능':`${st.name} 정화 후 해금`}</p></article>`).join('')}</div><button data-close>닫기</button>`);
 }
}
